from importlib.machinery import SourceFileLoader
w=SourceFileLoader('w','.literalgen-state/de-en-ru/1sa-root-native-write.py').load_module()
r=[
('Und David floh von Najoth in Rama und kam und sagte vor Jonathan: „Was habe ich getan, was ist meine Schuld, und was ist meine Sünde vor deinem Vater, dass er meine Seele sucht?“','Schuld und Sünde sind ausdrücklich als Hauptwörter genannt; gesucht wird seine Seele.'),
('Und er sagte zu ihm: „Fern sei es! Du wirst nicht sterben. Siehe, mein Vater tut keine große oder kleine Sache, ohne mein Ohr aufzudecken; und warum sollte mein Vater diese Sache vor mir verbergen? Das ist nicht so.“','Das Ohr steht im Singular.'),
('Und David schwor weiter und sagte: „Dein Vater weiß gewiss, dass ich Gnade in deinen Augen gefunden habe; und er sagte: ‚Jonathan soll dies nicht wissen, damit er nicht betrübt wird.‘ Aber so wahr der HERR lebt und deine Seele lebt, es ist nur ein Schritt zwischen mir und dem Tod.“','Das Wissen ist durch Wiederholung des Verbstamms verstärkt; die Rede des Vaters wird mit Sagen eingeführt.'),
('Und Jonathan sagte zu David: „Was deine Seele sagt, werde ich für dich tun.“','Genannt ist die Seele und ihr Sagen, nicht das Begehren des Herzens.'),
('Und David sagte zu Jonathan: „Siehe, morgen ist Neumond, und ich soll gewiss beim König sitzen, um zu essen; lass mich gehen, und ich werde mich im Feld bis zum Abend des dritten Tages verbergen.','Jonathan wird ausdrücklich genannt; das Sitzen ist durch Wiederholung bekräftigt.'),
('Wenn dein Vater mich gewiss vermisst, sollst du sagen: ‚David hat mich dringend gebeten, nach Bethlehem, seiner Stadt, zu laufen, denn dort ist das jährliche Schlachtopfer für die ganze Sippe.‘','Vermissen und Bitten sind beide durch Wiederholung des Verbstamms verstärkt.'),
('Wenn er so sagt: ‚Gut‘, ist Friede für deinen Knecht; und wenn er heftig zornig wird, dann wisse, dass das Böse bei ihm fest beschlossen ist.','Die Friedensformel steht ausdrücklich da; das Zornigwerden ist bekräftigt.'),
('Und erweise deinem Knecht Güte, denn du hast deinen Knecht mit dir in einen Bund des HERRN gebracht. Und wenn Schuld an mir ist, töte du mich; und warum solltest du mich zu deinem Vater bringen?“','Das Bringen in den Bund ist ausdrücklich genannt; „dein Knecht“ wird wiederholt.'),
('Und Jonathan sagte: „Fern sei dies von dir! Wenn ich gewiss weiß, dass das Böse bei meinem Vater beschlossen ist, über dich zu kommen, sollte ich es dir dann nicht berichten?“','Das Wissen ist durch Wiederholung des Verbstamms verstärkt.'),
('Und David sagte zu Jonathan: „Wer wird es mir berichten, oder was, wenn dein Vater dir hart antwortet?“','Jonathan wird ausdrücklich genannt; die beiden Fragen sind mit „oder“ verbunden.'),
('Und Jonathan sagte zu David: „Komm, und lass uns ins Feld hinausgehen!“ Und beide gingen ins Feld hinaus.','Nah am Hebräischen.'),
('Und Jonathan sagte zu David: „HERR, Gott Israels! Wenn ich meinen Vater um diese Zeit morgen oder am dritten Tag ausforsche, und siehe, er ist David gut gesinnt, werde ich dann nicht zu dir senden und dein Ohr aufdecken?','Das Aufdecken des Ohrs steht im Singular; das Benachrichtigen ist als verneinte Frage ausgedrückt.'),
('So tue der HERR Jonathan und so füge er hinzu! Wenn meinem Vater aber das Böse gegen dich gefällt, werde ich dein Ohr aufdecken und dich fortschicken, und du sollst in Frieden gehen. Und der HERR sei mit dir, wie er mit meinem Vater gewesen ist.','Der Schwur nennt das Hinzufügen ausdrücklich; beim Aufdecken steht ein einzelnes Ohr.'),
('Und wenn ich noch lebe, wirst du mir dann nicht die Güte des HERRN erweisen, damit ich nicht sterbe?','Die Bitte schließt ausdrücklich ein, dass er nicht sterben möge; sie untersagt nicht das Erweisen der Güte.'),
('Und du sollst deine Güte von meinem Haus in Ewigkeit nicht abschneiden, auch nicht, wenn der HERR die Feinde Davids, jeden Einzelnen, vom Angesicht des Erdbodens abschneidet.“','Die Güte wird bildlich abgeschnitten; das Angesicht des Erdbodens wird ausdrücklich genannt.'),
('Und Jonathan schloss einen Bund mit dem Haus Davids: „Der HERR fordere es von der Hand der Feinde Davids!“','Nah am Hebräischen.'),
('Und Jonathan ließ David erneut schwören, weil er ihn liebte; denn er liebte ihn mit der Liebe seiner Seele.','Jonathan lässt David schwören, statt selbst David zu schwören.'),
('Und Jonathan sagte zu ihm: „Morgen ist Neumond, und du wirst vermisst werden, denn dein Sitz wird vermisst werden.','Das Vermissen ist bei ihm und seinem Sitz wiederholt.'),
('Und am dritten Tag sollst du weit hinabgehen und an den Ort kommen, wo du dich am Tag der Tat verborgen hattest, und dich neben den Stein Asel setzen.','Der frühere Tag heißt wörtlich „Tag der Tat“; ein Werktag wird nicht eigens benannt.'),
('Und ich werde drei Pfeile an seiner Seite schießen, als schösse ich auf ein Ziel.','Nah am Hebräischen.'),
('Und siehe, ich werde den Knaben senden: ‚Geh, suche die Pfeile!‘ Wenn ich dem Knaben gewiss sage: ‚Siehe, die Pfeile sind von dir aus hierher; hole es!‘, dann komm, denn Friede ist für dich, und es ist nichts, so wahr der HERR lebt.','Das Sagen ist bekräftigt; beim Holen steht ein Einzahlobjekt.'),
('Und wenn ich so zum Jüngling sage: ‚Siehe, die Pfeile sind von dir aus weiter hinaus‘, dann geh, denn der HERR hat dich fortgeschickt.','Das Fortschicken hat den HERRN selbst zum Subjekt, ohne eigenes Lassen.'),
('Und die Sache, die wir, ich und du, geredet haben: Siehe, der HERR ist zwischen mir und dir in Ewigkeit.“','Nah am Hebräischen.'),
('Und David verbarg sich im Feld; und der Neumond kam, und der König setzte sich zum Brot, um zu essen.','Das Brot wird ausdrücklich genannt.'),
('Und der König saß auf seinem Sitz wie Mal um Mal, auf dem Sitz an der Wand; und Jonathan stand auf, und Abner saß an Sauls Seite, und Davids Platz wurde vermisst.','Nah am Hebräischen.'),
('Und Saul sagte an jenem Tag nichts, denn er sagte: „Ein Vorfall ist es; er ist nicht rein, denn er ist nicht rein.“','Die Unreinheit wird ausdrücklich wiederholt.'),
('Und am nächsten Tag, dem zweiten des Neumonds, wurde Davids Platz vermisst; und Saul sagte zu Jonathan, seinem Sohn: „Warum ist der Sohn Isais weder gestern noch heute zum Brot gekommen?“','Der zweite Tag wird ausdrücklich genannt; das Essen heißt Brot.'),
('Und Jonathan antwortete Saul: „David hat mich dringend gebeten, nach Bethlehem gehen zu dürfen.','David wird ausdrücklich genannt; das Bitten ist bekräftigt.'),
('Und er sagte: ‚Lass mich doch gehen, denn wir haben ein Schlachtopfer der Sippe in der Stadt, und mein Bruder hat es mir geboten. Und nun, wenn ich Gnade in deinen Augen gefunden habe, lass mich doch entkommen und meine Brüder sehen.‘ Darum ist er nicht an den Tisch des Königs gekommen.“','Das Entkommen wird ausdrücklich gesagt; die Bittepartikel kommt zweimal vor.'),
('Und Sauls Zorn entbrannte gegen Jonathan, und er sagte zu ihm: „Du Sohn einer verkehrten, widerspenstigen Frau! Weiß ich nicht, dass du den Sohn Isais erwählst, zu deiner Schande und zur Schande der Blöße deiner Mutter?','Die Beschimpfung nennt einen Sohn und seine Mutter; ihre Blöße wird ausdrücklich erwähnt.'),
('Denn alle Tage, die der Sohn Isais auf dem Erdboden lebt, wirst du nicht gefestigt werden, du und dein Königtum. Und nun sende hin und hole ihn zu mir, denn er ist ein Sohn des Todes.“','Das Königtum wird ausdrücklich genannt; die Todesbestimmung lautet bildlich „Sohn des Todes“.'),
('Und Jonathan antwortete Saul, seinem Vater, und sagte zu ihm: „Warum soll er getötet werden? Was hat er getan?“','Die Frage nennt das Getötetwerden passiv, nicht nur das Sterben.'),
('Und Saul schleuderte den Speer nach ihm, um ihn zu schlagen; und Jonathan erkannte, dass bei seinem Vater beschlossen war, David zu töten.','Das Schleudern ist als Handlung erzählt, nicht ein bereits gelungenes Aufspießen.'),
('Und Jonathan stand vom Tisch auf in brennendem Zorn und aß am zweiten Tag des Neumonds kein Brot, denn er war um David betrübt, weil sein Vater ihn beschämt hatte.','Jonathan wird ausdrücklich als der Aufstehende genannt; die Handlung des Vaters ist Beschämung.'),
('Und am Morgen ging Jonathan ins Feld hinaus zum verabredeten Treffen mit David, und ein kleiner Knabe war bei ihm.','Der Termin ist mit David verbunden, ohne ihn ausdrücklich zum Festlegenden zu machen.'),
('Und er sagte zu seinem Knaben: „Lauf, suche doch die Pfeile, die ich schieße!“ Der Knabe lief, und er schoss den Pfeil über ihn hinaus.','Genannt ist sein Knabe; das Suchen enthält eine Bittepartikel.'),
('Und der Knabe kam bis an den Ort des Pfeils, den Jonathan geschossen hatte; und Jonathan rief dem Knaben nach und sagte: „Ist der Pfeil nicht von dir aus weiter hinaus?“','Der Hinweis auf den Pfeil ist als verneinte Frage formuliert.'),
('Und Jonathan rief dem Knaben nach: „Schnell, eile, bleib nicht stehen!“ Und Jonathans Knabe sammelte die Pfeile und kam zu seinem Herrn.','Jonathan wird beim Rufen ausdrücklich genannt; der Knabe kommt zu seinem Herrn.'),
('Und der Knabe wusste nichts; nur Jonathan und David wussten die Sache.','Nah am Hebräischen.'),
('Und Jonathan gab seine Geräte dem Knaben, der bei ihm war, und sagte zu ihm: „Geh, bring sie in die Stadt!“','Die Gegenstände sind allgemein Geräte, nicht ausdrücklich Waffen.'),
('Der Knabe ging, und David stand von der Südseite auf und fiel auf sein Gesicht zur Erde und warf sich dreimal nieder; und sie küssten einander und weinten miteinander, bis David noch mehr weinte.','Der abschließende Vergleich ist an David gebunden; ein ausdrücklicher Superlativ steht nicht da.'),
('Und Jonathan sagte zu David: „Geh in Frieden, da wir beide im Namen des HERRN geschworen und gesagt haben: ‚Der HERR sei zwischen mir und dir und zwischen meinem Samen und deinem Samen in Ewigkeit!‘“ Und er stand auf und ging, und Jonathan kam in die Stadt.','Vor Jonathans Gang in die Stadt steht ein eigener Satz über das Aufstehen und Gehen eines ungenannten Mannes.')]
w.write(20,'de',r)
